package com.fitnessapp.gamification.achievement;
import com.fitnessapp.appAuth.model.entity.UserEntity; import jakarta.persistence.*; import lombok.Getter; import lombok.NoArgsConstructor; import java.time.Instant;
@Entity @Table(name="app_user_achievements",uniqueConstraints=@UniqueConstraint(name="uk_user_achievement_code",columnNames={"user_id","achievement_code"}),indexes=@Index(name="idx_achievement_user_unlocked",columnList="user_id,unlocked_at")) @Getter @NoArgsConstructor
public class UserAchievementEntity { @Id @GeneratedValue(strategy=GenerationType.IDENTITY) private Long id; @ManyToOne(fetch=FetchType.LAZY,optional=false) @JoinColumn(name="user_id",nullable=false) private UserEntity user; @Enumerated(EnumType.STRING) @Column(name="achievement_code",nullable=false,length=40) private AchievementCode code; @Column(name="unlocked_at",nullable=false) private Instant unlockedAt; public UserAchievementEntity(UserEntity u,AchievementCode c){user=u;code=c;unlockedAt=Instant.now();}}
